SELECT percentile_cont(0.75) within GROUP (ORDER BY icustays.los) AS percentile_75 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) BETWEEN 68 AND 78 AND admissions.admission_type_id IN (108077001, 108077002) AND icustays.los IS NOT NULL;